// Development harness: docs/dev/features.json → docs/dev/FEATURES.md, harness.json → src/design/tokens.ts,
// and checks that both generated files are current and that every feature points at real screens, contracts and tests.
// `node scripts/dev-harness.mjs` writes the generated files; check-harness imports checkDev().
import assert from 'node:assert/strict';
import { access, readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const FEATURES = 'docs/dev/features.json';
const FEATURES_MD = 'docs/dev/FEATURES.md';
const TOKENS = 'src/design/tokens.ts';
const PHASES = ['기반', '계정', '창간·발행', '읽기', '내 잡지', '관계', '계정 관리', '운영'];
const exists = (rel) => access(path.join(root, rel)).then(() => true, () => false);

async function load() {
  const manifest = JSON.parse(await readFile(path.join(root, 'harness.json'), 'utf8'));
  const dev = JSON.parse(await readFile(path.join(root, FEATURES), 'utf8'));
  const { PAINT, COLOR_ORDER } = await import(pathToFileURL(path.join(root, manifest.activeDesign.library)).href);
  return { manifest, dev, PAINT, COLOR_ORDER };
}

function featuresMarkdown(dev) {
  const screens = Object.fromEntries(dev.screens.map((s) => [s.id, s]));
  const list = (items) => (items.length ? items.map((t) => `- ${t}`).join('\n') : '- 없음');
  const out = [
    '# 기능 개발 목록',
    '',
    `> 자동 생성 파일이다. [features.json](features.json)을 고치고 \`npm run dev:docs\`로 다시 만든다. 개발 방법은 [개발 가이드](README.md)에 있다. (기준일 ${dev.updatedAt})`,
    '',
    '| ID | 기능 | 단계 | 목업 화면 | 계약 | 먼저 할 것 | 상태 |',
    '|---|---|---|---|---|---|---|',
    ...dev.features.map((f) => `| [${f.id}](#${f.id.toLowerCase()}) | ${f.title} | ${f.phase} ${PHASES[f.phase]} | ${f.screens.join(' ') || '—'} | ${f.contracts.join(' ')} | ${f.dependsOn.join(' ') || '—'} | ${f.status} |`),
    '',
  ];
  for (const f of dev.features) {
    out.push(`## ${f.id}`, '', `**${f.title}** · ${f.phase}단계 ${PHASES[f.phase]} · 상태 \`${f.status}\``, '', f.summary, '');
    if (f.screens.length) {
      out.push('**목업 화면**', '', f.screens.map((id) => `[${id} ${screens[id].title}](${screens[id].image.replace('docs/dev/', '')})`).join(' · '), '');
    }
    out.push(`**지킬 계약** ${f.contracts.join(', ')} · **먼저 할 것** ${f.dependsOn.join(', ') || '없음'}`, '');
    out.push('**앱(Expo)**', '', list(f.client), '', '**서버 (초안)**', '', list(f.server), '', '**합격 기준**', '', list(f.acceptance), '', '**추가할 테스트**', '', list(f.tests.map((t) => `\`${t}\``)), '');
    if (f.openDecisions.length) out.push('**사용자 결정이 필요한 것**', '', list(f.openDecisions), '');
  }
  out.push('## 화면 등록부', '', '| 화면 | 이름 | 목업 경로 | 참고 그림 | 피그마 노드 |', '|---|---|---|---|---|');
  for (const s of dev.screens) out.push(`| ${s.id} | ${s.title} | \`${s.route}\` | [그림](${s.image.replace('docs/dev/', '')}) | ${s.figma || '—'} |`);
  return `${out.join('\n')}\n`;
}

function tokensSource(manifest, PAINT, COLOR_ORDER) {
  const t = manifest.designTokens;
  const scale = manifest.tokenScale;
  const data = {
    color: { paper: t.paper, ink: t.ink, muted: t.muted, hairline: t.hairline, ...scale.colors },
    paint: Object.fromEntries(COLOR_ORDER.map((k) => [k, { nameKo: PAINT[k].name, nameEn: PAINT[k].en, hex: PAINT[k].hex, asset: `esel-paint-${k}.png` }])),
    paintOrder: COLOR_ORDER,
    glass: manifest.glass,
    font: manifest.typography,
    spacing: scale.spacing,
    radius: scale.radius,
    shadow: scale.shadow,
    size: scale.size,
    motion: { easing: manifest.motion.easing, durationMs: manifest.motion.durations },
  };
  return `// Generated by \`npm run dev:docs\` from harness.json and the canvas generator. Do not edit by hand.
// Values follow the design boards (docs/design/README.md). Change harness.json, then regenerate.
export const tokens = ${JSON.stringify(data, null, 2)} as const;

export type PaintKey = keyof typeof tokens.paint;
`;
}

export async function generated() {
  const { manifest, dev, PAINT, COLOR_ORDER } = await load();
  return { [FEATURES_MD]: featuresMarkdown(dev), [TOKENS]: tokensSource(manifest, PAINT, COLOR_ORDER) };
}

export async function checkDev() {
  const { manifest, dev } = await load();
  const app = await readFile(path.join(root, manifest.appMockup.source.find((f) => f.endsWith('app.js'))), 'utf8');
  const routes = new Set([...app.matchAll(/SCREENS(?:\.([a-zA-Z]+)|\['([a-z-]+)'\]) =/g)].map((m) => m[1] || m[2]));
  const screenIds = new Set();
  for (const s of dev.screens) {
    assert(!screenIds.has(s.id), `화면 ID 중복: ${s.id}`);
    screenIds.add(s.id);
    assert(routes.has(s.route), `목업에 없는 경로: ${s.id} → ${s.route}`);
    assert(await exists(s.image), `참고 그림 없음: ${s.image} (npm run mockup:capture)`);
  }
  const ids = new Map(dev.features.map((f) => [f.id, f]));
  assert.equal(ids.size, dev.features.length, '기능 ID 중복');
  const usedScreens = new Set();
  const usedContracts = new Set();
  for (const f of dev.features) {
    assert(/^DEV-\d{2}$/.test(f.id), `기능 ID 형식: ${f.id}`);
    assert(Number.isInteger(f.phase) && f.phase >= 0 && f.phase < PHASES.length, `단계 범위: ${f.id}`);
    assert(dev.statuses.includes(f.status), `상태 값: ${f.id} ${f.status}`);
    for (const key of ['summary', 'screens', 'contracts', 'dependsOn', 'client', 'server', 'acceptance', 'tests', 'openDecisions']) assert(key in f, `${f.id}에 ${key} 없음`);
    for (const s of f.screens) { assert(screenIds.has(s), `${f.id}: 등록부에 없는 화면 ${s}`); usedScreens.add(s); }
    for (const c of f.contracts) { assert(manifest.productContracts.includes(c), `${f.id}: 없는 계약 ${c}`); usedContracts.add(c); }
    for (const d of f.dependsOn) {
      assert(ids.has(d), `${f.id}: 없는 선행 기능 ${d}`);
      assert(ids.get(d).phase <= f.phase, `${f.id}: 뒤 단계 기능(${d})에 기대고 있음`);
    }
    assert(f.acceptance.length > 0 || f.status === 'todo', `${f.id}: 합격 기준 없음`);
    if (f.status === 'done') for (const t of f.tests) assert(await exists(t), `${f.id}는 done인데 테스트 파일이 없음: ${t}`);
  }
  const visit = (id, trail = []) => { assert(!trail.includes(id), `선행 기능 순환: ${[...trail, id].join(' → ')}`); for (const d of ids.get(id).dependsOn) visit(d, [...trail, id]); };
  for (const id of ids.keys()) visit(id);
  for (const s of screenIds) assert(usedScreens.has(s), `어느 기능에도 연결되지 않은 화면: ${s}`);
  for (const c of manifest.productContracts) assert(usedContracts.has(c), `어느 기능에도 배정되지 않은 계약: ${c}`);
  for (const [rel, text] of Object.entries(await generated())) {
    const current = await readFile(path.join(root, rel), 'utf8').catch(() => '');
    assert.equal(current, text, `${rel}가 최신이 아님. npm run dev:docs`);
  }
  return { features: dev.features.length, screens: dev.screens.length, done: dev.features.filter((f) => f.status === 'done').length };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  for (const [rel, text] of Object.entries(await generated())) {
    await mkdir(path.dirname(path.join(root, rel)), { recursive: true });
    await writeFile(path.join(root, rel), text);
  }
  console.log(`개발 문서 생성: ${FEATURES_MD}, ${TOKENS}`);
}
